rows_data = cells('Allowed assignments', 'L812:N820')
# Tasks: Inspect, Pack, Polish
# Workers: Dune, Birch, Aster, Cedar
# If Dune is unavailable, workers left are Birch, Aster, Cedar (3 workers).
# Tasks are Inspect, Pack, Polish (3 tasks).
import itertools
tasks = ['Inspect', 'Pack', 'Polish']
workers = ['Birch', 'Aster', 'Cedar']
costs = {}
for r in rows_data:
    if r[1] != 'Dune':
        costs[(r[0], r[1])] = r[2]

min_cost = float('inf')
for p in itertools.permutations(workers, len(tasks)):
    possible = True
    current_cost = 0
    for t, w in zip(tasks, p):
        if (t, w) in costs:
            current_cost += costs[(t, w)]
        else:
            possible = False
            break
    if possible:
        if current_cost < min_cost:
            min_cost = current_cost
result = min_cost

