sheet = 'Transition probabilities'
rows = data_rows(sheet, {'H':'string', 'I':'string', 'G':'number'}, 390, 398)
trans = {}
for r in rows:
    f = cell(sheet, f'H{r}')
    t = cell(sheet, f'I{r}')
    p = num(sheet, f'G{r}')
    trans[(f, t)] = p

states = ['Idle', 'Active', 'Done']
# step 0: certainly Idle
dist = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}

for step in range(4):
    new_dist = {s: 0.0 for s in states}
    for s in states:
        for t in states:
            p = trans.get((s, t), 0.0)
            new_dist[t] += dist[s] * p
    dist = new_dist

result = round(dist['Done'], 6)

sheet = 'Transition probabilities'
rows = data_rows(sheet, {'G': 'number', 'H': 'string', 'I': 'string'}, 390, 398)
prob = values(sheet, [f'G{r}' for r in rows])
from_s = values(sheet, [f'H{r}' for r in rows])
to_s = values(sheet, [f'I{r}' for r in rows])
trans = {(f, t): p for f, t, p in zip(from_s, to_s, prob)}
states = ['Idle', 'Active', 'Done']
vector = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}
for step in range(4):
    new_vector = {'Idle': 0.0, 'Active': 0.0, 'Done': 0.0}
    for f in states:
        for t in states:
            p = trans.get((f, t), 0.0)
            new_vector[t] += vector[f] * p
    vector = new_vector
result = round(vector['Done'], 6)

rows = cells('Transition probabilities', 'G390:I398')
states = ['Active', 'Idle', 'Done']
s2i = {s: i for i, s in enumerate(states)}
P = [[0.0]*3 for _ in range(3)]
for r in rows:
    P[s2i[r[1]]][s2i[r[2]]] = float(r[0])
pi = [0.0, 1.0, 0.0]
for _ in range(4):
    npi = [0.0, 0.0, 0.0]
    for i in range(3):
        for j in range(3):
            npi[j] += pi[i] * P[i][j]
    pi = npi
result = round(pi[s2i['Done']], 6)

